#!/usr/bin/env bash
#
# mayhem/build.sh — build the fuzz harnesses and the unit-test oracle for livekit/client-sdk-cpp.
#
# Upstream's own build runs cargo (the Rust livekit-ffi cdylib: libwebrtc + tokio, fetched from the
# network) and FetchContent for protobuf/spdlog/gtest, none of which can run air-gapped. The C++ SDK
# talks to Rust only through four C symbols, so this build compiles the SDK's C++ sources (src/*.cpp)
# plus the protobuf code generated from the FFI protocol (mayhem/ffi-protocol, a copy of
# client-sdk-rust/livekit-ffi/protocol) against distro packages, and links mayhem/ffi_stub.cpp in place
# of the Rust library. Everything below is a plain re-run on an already-built tree.
set -euo pipefail

[ -n "${SOURCE_DATE_EPOCH:-}" ] || unset SOURCE_DATE_EPOCH

: "${SANITIZER_FLAGS=-fsanitize=address,undefined -fno-sanitize-recover=all -fno-omit-frame-pointer}"
: "${DEBUG_FLAGS:=-g -gdwarf-3}"
: "${CC:=clang}" ; : "${CXX:=clang++}" ; : "${LIB_FUZZING_ENGINE:=-fsanitize=fuzzer}"
: "${MAYHEM_JOBS:=$(nproc)}"
: "${COVERAGE_FLAGS=}"
: "${STANDALONE_FUZZ_MAIN:=/opt/mayhem/StandaloneFuzzTargetMain.c}"
export SANITIZER_FLAGS DEBUG_FLAGS CC CXX LIB_FUZZING_ENGINE MAYHEM_JOBS COVERAGE_FLAGS

cd "$SRC"
M="$SRC/mayhem"
GEN="$SRC/build-mayhem/gen"          # generated protobuf code + build.h (shared by both builds)
FUZZ_OBJ="$SRC/build-mayhem/fuzz-obj"
TEST_DIR="$SRC/build-tests"

rm -rf "$SRC/build-mayhem" "$TEST_DIR"
mkdir -p "$GEN/livekit" "$FUZZ_OBJ" "$TEST_DIR/obj"

# ---- generated sources ------------------------------------------------------------------------
protoc --proto_path="$M/ffi-protocol" --cpp_out="$GEN" "$M"/ffi-protocol/*.proto
sed -e 's|@GENERATED_COMMENT@|generated by mayhem/build.sh|' \
    -e 's|@LIVEKIT_VERSION@|0.0.0|' \
    -e 's|@BUILD_DATE@|1970-01-01T00:00:00Z|' \
    -e 's|@GIT_COMMIT@|unknown|' \
    "$SRC/build.h.in" > "$GEN/livekit/build.h"

# The SDK's C++ translation units. uniffi_bindgen_adapter.cpp needs the header generated from the
# Rust crate and only reports the Rust build version, so it is left out.
SDK_SRCS=()
for f in "$SRC"/src/*.cpp "$SRC"/src/trace/*.cpp; do
  case "$f" in */uniffi_bindgen_adapter.cpp) continue ;; esac
  SDK_SRCS+=("$f")
done
PB_SRCS=("$GEN"/*.pb.cc)

PKG="$(pkg-config --cflags spdlog protobuf libcurl)"
PKG_LIBS="$(pkg-config --libs spdlog protobuf libcurl) -lpthread"
INC=(-I"$GEN" -I"$SRC/include" -I"$SRC/src" -I"$SRC/src/trace" -I"$M/ffi-include")
DEFS=(-DLIVEKIT_BUILDING_SDK=1 -DSPDLOG_ACTIVE_LEVEL=0)

# compile_all <objdir> <flags...> -- <sources...>: compile in parallel, one object per source.
compile_all() {
  local outdir="$1"; shift
  local flags=()
  while [ "$1" != "--" ]; do flags+=("$1"); shift; done
  shift
  printf '%s\0' "$@" | xargs -0 -P "$MAYHEM_JOBS" -I{} bash -c '
    out="$1"; shift; src="$1"; shift
    exec "$@" -c "$src" -o "$out/$(basename "$src").$(echo "$src" | cksum | cut -d" " -f1).o"
  ' _ "$outdir" {} "$CXX" "${flags[@]}"
}

# ---- 1) fuzz build: SDK + generated protobuf code, ASan+UBSan(halting)+SanCov, DWARF 3 -----------
# Left unquoted on purpose: these are flag lists. -fsanitize=fuzzer-no-link instruments the SDK
# itself for coverage regardless of SANITIZER_FLAGS.
FUZZ_FLAGS=(-std=c++17 -O1 -w -fPIC -fsanitize=fuzzer-no-link $SANITIZER_FLAGS $DEBUG_FLAGS)
compile_all "$FUZZ_OBJ" "${FUZZ_FLAGS[@]}" $PKG "${INC[@]}" "${DEFS[@]}" -- "${SDK_SRCS[@]}" "${PB_SRCS[@]}" "$M/ffi_stub.cpp"
rm -f "$GEN/libsdk.a"
ar rcs "$GEN/libsdk.a" "$FUZZ_OBJ"/*.o

"$CXX" $SANITIZER_FLAGS $DEBUG_FLAGS -c "$M/lsan_off.cc" -o "$FUZZ_OBJ/lsan_off.lo"
"$CC" $SANITIZER_FLAGS $DEBUG_FLAGS -c "$STANDALONE_FUZZ_MAIN" -o "$GEN/standalone_main.o"

HARNESSES=(fuzz_audio_frame fuzz_token_source fuzz_ffi_event)
for h in "${HARNESSES[@]}"; do
  HFLAGS=(-std=c++17 -O1 -w $SANITIZER_FLAGS $DEBUG_FLAGS $PKG "${INC[@]}" "${DEFS[@]}")
  "$CXX" "${HFLAGS[@]}" $LIB_FUZZING_ENGINE "$M/$h.cc" "$FUZZ_OBJ/lsan_off.lo" "$GEN/libsdk.a" $PKG_LIBS -o "/mayhem/$h"
  "$CXX" "${HFLAGS[@]}" "$M/$h.cc" "$FUZZ_OBJ/lsan_off.lo" "$GEN/standalone_main.o" "$GEN/libsdk.a" $PKG_LIBS -o "/mayhem/$h-standalone"
done

# ---- 2) test build: upstream's gtest unit tests, normal flags (no sanitizers, no -gdwarf-3) -----
# The tests that need a live Rust FFI (rooms, tracks, sources, streams) cannot run against the stub;
# these are the ones whose subject is pure C++ and which pass unchanged.
UNIT_TESTS=(test_audio_frame test_token_source test_result test_rpc_error test_data_track_frame
            test_data_track_error test_room_event_types)
TEST_FLAGS=(-std=c++17 -O1 -w -fPIC $COVERAGE_FLAGS)
TEST_SRCS=("${SDK_SRCS[@]}" "${PB_SRCS[@]}" "$M/ffi_stub.cpp" "$SRC/src/tests/benchmark/benchmark_utils.cpp")
for t in "${UNIT_TESTS[@]}"; do TEST_SRCS+=("$SRC/src/tests/unit/$t.cpp"); done
TINC=("${INC[@]}" -I"$SRC/src/tests/benchmark" -I"$SRC/src/tests/common")
TDEFS=("${DEFS[@]}" -DLIVEKIT_TEST_ACCESS -DLIVEKIT_ROOT_DIR="\"$SRC\"")
compile_all "$TEST_DIR/obj" "${TEST_FLAGS[@]}" $PKG "${TINC[@]}" "${TDEFS[@]}" -- "${TEST_SRCS[@]}"
"$CXX" "${TEST_FLAGS[@]}" "$TEST_DIR"/obj/*.o -lgtest -lgtest_main $PKG_LIBS -o "$TEST_DIR/livekit_unit_tests"
